// IsCoachedByActor returns true if the user with the given kaid (coachee) is
// coached by the actor (coach).
//
// It returns false if the coachee is not coached by the actor.  It also
// returns false, and additionally logs an error, if we were unable to
// determine whether that is the case.  To handle errors explicitly, see
// IsCoachedByActorErr.
//
//ka:permission-check
func IsCoachedByActor(ctx aclContext, coacheeKaid string) bool {
	ok, err := IsCoachedByActorErr(ctx, coacheeKaid)
	maybeLog(ctx, err)
	return ok
}

// IsCoachedByActorErr returns true if the use with the given kaid (coachee) is
// coached by the actor (coach).
//
// It returns false if the coachee is not coached by the actor, and (false
// and) an error only if we were unable to determine whether the actor coaches
// the given user.  To simply log and deny access on error, see
// IsCoachedByActor.
//
//ka:permission-check
var IsCoachedByActorErr = cache.Cache(
	_isCoachedByActorErr,
	cache.In(lib.RequestCache),
	cache.SkipCacheOnError,
)

func _isCoachedByActorErr(ctx aclContext, coacheeKaid string) (bool, error) {
	// early-out if we're a service-admin query; those don't have actors.
	if isServiceAdminQuery(ctx) {
		return false, nil
	}

	// early-out if the current user is a phantom or pre-phantom -- only full
	// user accounts can be coaches.
	actor, err := ctx.RequestUser()
	if err != nil {
		return false, err
	} else if actor.Kaid == "" || actor.IsPhantom {
		return false, nil
	}

	_ = `# @genqlient
		query PkgAcl_IsCoachedByACL($coachKaid: String!, $coacheeKaid: String!) {
			isCoachedBy(coachKaid: $coachKaid, coacheeKaid: $coacheeKaid)
		}
	`
	resp, err := genqlient.PkgAcl_IsCoachedByACL(
		ctx, ctx.GraphQL().AsServiceAdmin(), actor.Kaid, coacheeKaid)
	return resp.IsCoachedBy, err

// ManyCoachedByActorErr runs a cross service call to determine which of the
// provided coachee kaids are coached by the actor.
//
// It returns a map of kaids to booleans indicating which kaid is coached by
// the actor. If an error occurs, then we return an empty map.
// To simply log and deny access on error, see ManyCoachedByActor.
//
//ka:permission-check
func ManyCoachedByActorErr(ctx aclContext, coacheeKaids []string) (map[string]bool, error) {
	result := map[string]bool{}

	// early-out if we're a service-admin query; those don't have actors.
	if isServiceAdminQuery(ctx) {
		return result, nil
	}

	// early-out if the current user is a phantom or pre-phantom -- only full
	// user accounts can be coaches.
	actor, err := ctx.RequestUser()
	if err != nil {
		return result, err
	} else if actor.Kaid == "" || actor.IsPhantom {
		return result, nil
	}

	_ = `# @genqlient
		query PkgAcl_ManyCoachedByACL($coachKaid: String!, $coacheeKaids: [String!]!) {
			manyCoachedBy(coachKaid: $coachKaid, coacheeKaids: $coacheeKaids)
		}
	`
	resp, err := genqlient.PkgAcl_ManyCoachedByACL(
		ctx, ctx.GraphQL().AsServiceAdmin(), actor.Kaid, coacheeKaids)
	if err != nil {
		return result, err
	}

	// The result from `manyCoachedBy` comes back in the same order in which
	// the coacheeKaids are provided.
	for i := range coacheeKaids {
		result[coacheeKaids[i]] = resp.ManyCoachedBy[i]
	}

	return result, err

// ManyCoachedBy determines who in the list of kaids is coached by a particular
// coach.
func ManyCoachedBy(ctx interface {
	kacontext.Base
	datastore.KAContext
},
	coachKaid string,
	coacheeKaids []string,
) ([]bool, error) {
	g := tracegroup.WithContext(&ctx)

	result := make([]bool, len(coacheeKaids))

	for i, coacheeKaid := range coacheeKaids {
		g.Go("check coach-coachee pair", func(ctx datastore.KAContext) error {
			_, err := getCoachCoacheePair(ctx, coachKaid, coacheeKaid)
			switch {
			case errors.Is(err, errors.NotFoundKind):
				result[i] = false
				return nil
			case err != nil:
				return err
			default:
				result[i] = true
				return nil
			}
		})
	}

	err := g.Wait()
	return result, err
}

// IsCoachedBy determines if a coachee is coached by a particular user.
func IsCoachedBy(ctx datastore.KAContext,
	coachKaid string,
	coacheeKaid string,
) (bool, error) {
	key := models.MakeCoachCoacheePairKey(coachKaid, coacheeKaid)
	query := datastore.NewQuery(models.CoachCoacheePairKind).FilterField("__key__", "=", key)
	return crud.HasAny(ctx, query)

// coachingLoader batches the actor-coaches-kaid lookups that the field
// resolvers of a roster issue one at a time. GraphQL resolves those fields
// concurrently, so the whole roster's lookups land in a single batch and
// become one manyCoachedBy call rather than one isCoachedBy call per student.
//
// acl.IsCoachedByActor is request-cached per coachee kaid, so it does not
// collapse a roster on its own: distinct students share no cache entry.
var CoachingLoader = dataloader.CachedLoader(_batchLoadCoaching)

// _batchLoadCoaching reports whether the actor coaches that kaid.
//
// A note on kacontext.Upgrade:
// pkg/lib/dataloader hands this function to dataloadgen, which calls it
// with a plain context.Context, so the resolver-caller's typed ktx can't reach
// it. This is the third-party entrypoint kacontext.Upgrade is meant for.
func _batchLoadCoaching(ctx context.Context, kaids []string) ([]bool, []error) {
	var ktx interface {
		gqlclient.KAContext
		log.KAContext
		web.AuthedUserContext
	} = kacontext.Upgrade(ctx) //nolint:ka-context // dataloadgen entrypoint

	coached, err := acl.ManyCoachedByActorErr(ktx, kaids)
	if err != nil {
		// The failure is not per-key, so report it against every key.
		errs := make([]error, len(kaids))
		for i := range errs {
			errs[i] = err
		}
		return make([]bool, len(kaids)), errs
	}

	out := make([]bool, len(kaids))
	for i, kaid := range kaids {
		out[i] = coached[kaid]
	}
	return out, nil

sessionsByConfig := make(
	map[string]map[string]*models.AIGuideEssaySession, len(kaidsByConfig),
)
errByConfig := map[string]error{}
for configID, kaids := range kaidsByConfig {
	sessions, err := essay_feedback.GetSessionByConfigIdAndKaids(
		ktx, configID, kaids,
	)
	if err != nil {
		// A failure is scoped to the config that failed. Batching must not
		// widen the blast radius: without this, one assignment's failed
		// query would error out a healthy assignment's roster too, whereas
		// the unbatched per-row calls failed independently.
		errByConfig[configID] = err
		continue
	}
	sessionsByConfig[configID] = sessions
}

found := make([]*models.AIGuideEssaySession, len(keys))
errs := make([]error, len(keys))
for i, key := range keys {
	if err, failed := errByConfig[key.ConfigID]; failed {
		errs[i] = err
		continue
	}
	found[i] = sessionsByConfig[key.ConfigID][key.Kaid]
}
return found, errs

// isActorCoachOrAdmin returns true if the kaid is the actor,
// is coached by the actor, or can be administered by the actor.
// Equivalent to Python's: (is_actor, is_coached_by_actor,
// is_limited_support_admin_for_user).
//
//ka:permission-check // resolvers can use this as their permission check
func isActorCoachOrAdmin(
	ctx interface {
		log.KAContext
		gqlclient.KAContext
		web.AuthedUserContext
	},
	kaid string,
) bool {
	// Check isActor first to avoid unnecessary permissions lookups.
	return isActor(ctx, kaid) ||
		isCoachedByActor(ctx, kaid) ||
		actorIsProgressViewingAdminForUser(ctx, kaid)
}

// isActorCoachOrAdminBatched: Like the non-batched isActorCoachOrAdmin,
// returns true if the kaid is the actor, is coached by the actor,
// or can be administered by the actor.
//
// This function passes the given kaid to a loader that batches concurrent
// coached-by checks.
// This is useful when you have a caller (likely a gql resolver) that
// fans out multiple permission checks to resolve data in a list.
// Example: a teacher is loading an entire classroom's data.
//
// If the caller is operating in a context where the larger request is
// scoped to a single learner's data and concurrent requests are
// not made, use the non-batched isActorCoachOrAdmin. Otherwise,
// serial requests will incur unnecessary wait time
// while they wait for concurrent requests that never arrive.
//
//ka:permission-check // resolvers can use this as their permission check
func isActorCoachOrAdminBatched(
	ctx interface {
		kacontext.Base
		log.KAContext
		gqlclient.KAContext
		web.AuthedUserContext
	},
	kaid string,
) bool {
	// Check isActor first to avoid unnecessary permissions lookups.
	if isActor(ctx, kaid) {
		return true
	}

	// Pass coached-by check to loader
	coached, err := essay_feedback_loaders.CoachingLoader(ctx).Load(ctx, kaid)
	if err != nil {
		// Match acl.IsCoachedByActor, which logs and denies rather than
		// failing the request, leaving the admin check below as the last word.
		ctx.Log().Error(err)
	} else if coached {
		return true
	}

	// The admin check has no batch form, so it stays per-kaid.
	// Runs when the kaid != actor and when actor != kaid's coach.
	return actorIsProgressViewingAdminForUser(ctx, kaid)

// Resolve the session for the given student and assignable entity
func (r *writingCoachAssignmentStudentDataResolver) Session(
	ctx context.Context,
	obj *graphql.WritingCoachAssignmentStudentData,
) (*graphql.ActiveEssaySession, error) {
	var ktx interface {
		kacontext.Base
		log.KAContext
		web.AuthedUserContext
		web.AuthedServiceContext
		gqlclient.KAContext
	} = kacontext.Upgrade(ctx)
	// A service-admin query has no logged-in actor.
	// If the actor is not a service admin,
	// the actor needs to be logged in to continue.
	isServiceAdmin := ktx.RequestIsServiceAdminQuery()
	if !isServiceAdmin && !acl.IsLoggedIn(ktx, acl.PhantomProhibited) {
		return nil, errors.Unauthorized()
	}

	// Using the batched permissions check because the
	// GraphQL executor calls this resolver concurrently,
	// once per entity.
	if !isServiceAdmin && !isActorCoachOrAdminBatched(ktx, obj.Kaid) {
		return nil, errors.Unauthorized(
			"User cannot access this Writing Coach session",
			errors.Fields{
				"kaid":                 obj.Kaid,
				"writingCoachConfigId": obj.AssignableEntityID,
			},
		)
	}

// isActorCoachOrAdmin returns true if the kaid is the actor,
// is coached by the actor, or can be administered by the actor.
// Equivalent to Python's: (is_actor, is_coached_by_actor,
// is_limited_support_admin_for_user).
//
//ka:permission-check // resolvers can use this as their permission check
func isActorCoachOrAdmin(
	ctx interface {
		log.KAContext
		gqlclient.KAContext
		web.AuthedUserContext
	},
	kaid string,
) bool {
	// Check isActor first to avoid unnecessary permissions lookups.
	return isActor(ctx, kaid) ||
		isCoachedByActor(ctx, kaid) ||
		actorIsProgressViewingAdminForUser(ctx, kaid)
}

